"""CPU-only R6 budget checks. Caller holds the single controller writer lock.

No Store permission, submission, settlement or budget refund occurs here.
Reservations remain charged even when an attempt or worker fails.
"""
import copy
import math


class BudgetError(ValueError):
    pass


def amount(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise BudgetError('Resource amount must be numeric')
    if not math.isfinite(value) or value < 0:
        raise BudgetError('Resource amount must be finite and nonnegative')
    return value


def totals(ledger):
    caps = ledger['caps']
    result = {k: amount(ledger['used'][k]) for k in caps}
    seen = set()
    for reservation in ledger['reservations']:
        key = reservation['event_key']
        if key in seen:
            raise BudgetError('Duplicate reservation event')
        seen.add(key)
        for resource, value in reservation['resources'].items():
            if resource not in caps:
                raise BudgetError('Unknown resource: ' + resource)
            result[resource] += amount(value)
    for resource, value in result.items():
        if value > amount(caps[resource]):
            raise BudgetError('Cap exceeded: ' + resource)
    return result


def reserve(ledger, *, event_key, resources, purpose, free_disk_bytes):
    """Return a new ledger; identical replays don't spend again, drift fails.

    event_key binds goal, event, job, input hash and role. Final/recovery use
    of protected capacity is explicit. Ordinary development cannot borrow it.
    Disk check subtracts all outstanding output reservations conservatively.
    """
    required = {'goal_id', 'event_id', 'job_id', 'input_sha256', 'role'}
    if set(event_key) != required or event_key['goal_id'] != ledger['goal_id']:
        raise BudgetError('Incomplete event identity')
    if not all(isinstance(v, str) and v for v in event_key.values()):
        raise BudgetError('Empty event identity')
    digest = event_key['input_sha256']
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
        raise BudgetError('Invalid input hash')
    if purpose not in {'development', 'confirmation_delivery', 'repair', 'final_review'}:
        raise BudgetError('Unknown reservation purpose')
    key = tuple(event_key[k] for k in sorted(required))
    # JSON round trips preserve this stable string; tuples are not persisted.
    import json
    key = json.dumps(key, separators=(',', ':'))
    entry = {'event_key': key, 'identity': event_key, 'resources': resources, 'purpose': purpose}
    for prior in ledger['reservations']:
        if prior['event_key'] == key:
            if prior != entry:
                raise BudgetError('Reservation replay drift')
            totals(ledger)
            return copy.deepcopy(ledger)
    candidate = copy.deepcopy(ledger)
    candidate['reservations'].append(copy.deepcopy(entry))
    usage = totals(candidate)
    if purpose == 'development':
        for resource, protected in ledger['protected_confirmation_delivery_repair'].items():
            # Protected use cannot accidentally become available to exploration.
            dev_used = amount(ledger['used'][resource])
            dev_used += sum(r['resources'].get(resource, 0) for r in candidate['reservations']
                            if r['purpose'] == 'development')
            if dev_used > ledger['caps'][resource] - amount(protected):
                raise BudgetError('Protected capacity: ' + resource)
    model_cap = ledger['caps']['automatic_model_sessions']
    other_models = sum(r['resources'].get('automatic_model_sessions', 0)
                       for r in candidate['reservations']
                       if r['purpose'] not in {'repair', 'final_review'})
    if other_models > model_cap - sum(ledger['protected_model_sessions'].values()):
        raise BudgetError('Protected review/repair sessions')
    for protected_role, count in ledger['protected_model_sessions'].items():
        outside_role = amount(ledger['used']['automatic_model_sessions'])
        outside_role += sum(r['resources'].get('automatic_model_sessions', 0)
                            for r in candidate['reservations']
                            if r['purpose'] != protected_role)
        if outside_role > model_cap - count:
            raise BudgetError('Protected model role: ' + protected_role)
    disk_key = 'output_actual_plus_unreleased_reservations_bytes'
    if amount(free_disk_bytes) - usage[disk_key] < ledger['disk_free_floor_bytes']:
        raise BudgetError('Disk floor after reservations')
    return candidate
"""R6 recovery journal, reusing rlflow atomic persistence and process identity.

This is not a launcher. The controller must hold this lock before calling any
mutation. An intent without authoritative completion never authorizes a retry.
"""
from contextlib import contextmanager
from pathlib import Path
import fcntl
import hashlib
import json
import os

from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_budget import reserve


class RecoveryError(RuntimeError):
    pass


def file_pin(path):
    path = Path(path).resolve()
    with path.open('rb') as stream:
        digest = hashlib.file_digest(stream, 'sha256').hexdigest()
    return {'path': str(path), 'sha256': digest}


def checked(pin):
    path = Path(pin['path'])
    if path.is_symlink() or file_pin(path) != pin:
        raise RecoveryError('PIN_DRIFT')
    return path


class Journal:
    def __init__(self, directory, stop_paths=()):
        self.directory = Path(directory)
        self.path = self.directory / 'state.json'
        self.stop_paths = [self.directory / 'STOP', *map(Path, stop_paths)]
        self._lock = None
        self._owner_pid = None

    @contextmanager
    def writer(self):
        if self._lock is not None:
            raise RecoveryError('NESTED_WRITER')
        self.directory.mkdir(parents=True, exist_ok=True)
        with (self.directory / 'writer.lock').open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            self._lock, self._owner_pid = lock, os.getpid()
            try:
                yield self
            finally:
                self._lock = self._owner_pid = None
                fcntl.flock(lock, fcntl.LOCK_UN)

    def require_writer(self):
        if self._lock is None or self._owner_pid != os.getpid():
            raise RecoveryError('SINGLE_WRITER_REQUIRED')

    def stopped(self):
        return [str(p) for p in self.stop_paths if p.exists()]

    def guard(self):
        self.require_writer()
        if self.stopped():
            raise RecoveryError('STOP_NEW_ACTIONS')

    def read(self):
        return json.loads(self.path.read_text())

    def save(self, state):
        self.require_writer()
        atomic(self.path, canonical(state) + b'\n')

    def initialize(self, budget):
        self.guard()
        if self.path.exists():
            raise RecoveryError('USE_EXISTING_STATE')
        self.save({'schema_version': 'r6-recovery/1', 'goal_id': budget['goal_id'],
                   'controller_identity': identity(os.getpid()), 'budget': budget,
                   'events': {}, 'duplicate_events_rejected': 0,
                   'status': 'CPU_PREPARE', 'current_job': None})

    def intent(self, event, *, kind, request, resources, purpose, free_disk_bytes):
        """Persist request and reservation in one transaction before side effects.

        Returns (key, fresh). False means inspect existing work, never launch.
        Input hash covers the full request, including executable/prompt/schema.
        """
        self.guard()
        if kind not in {'job', 'model', 'settle', 'postrun', 'cpu'}:
            raise RecoveryError('UNKNOWN_EVENT_KIND')
        if event.get('input_sha256') != sha(request):
            raise RecoveryError('REQUEST_IDENTITY_MISMATCH')
        state = self.read()
        key = sha(event)
        entry = {'identity': event, 'kind': kind, 'request': request,
                 'resources': resources, 'purpose': purpose}
        if key in state['events']:
            previous = state['events'][key]
            if any(previous[k] != v for k, v in entry.items()):
                raise RecoveryError('EVENT_REPLAY_DRIFT')
            state['duplicate_events_rejected'] += 1
            self.save(state)
            return key, False
        state['budget'] = reserve(state['budget'], event_key=event, resources=resources,
                                  purpose=purpose, free_disk_bytes=free_disk_bytes)
        state['events'][key] = {**entry, 'status': 'INTENT', 'process': None,
                                'receipt': None}
        self.save(state)
        return key, True

    def bind_process(self, key, process):
        self.require_writer()
        if not owns(process):
            raise RecoveryError('PROCESS_IDENTITY_NOT_LIVE')
        state = self.read()
        entry = state['events'][key]
        if entry['status'] != 'INTENT' or entry['process'] is not None:
            raise RecoveryError('PROCESS_ALREADY_BOUND')
        entry.update(process=process, status='RUNNING')
        self.save(state)

    def observe(self, key, *, receipt_path=None, exact_job=None):
        """Read-only recovery decision based on a receipt or a live exact handle.

        STOP never suppresses observation/cleanup of an existing owned job.
        A callback result must include the exact event job ID and request hash.
        A job receipt is not settlement; returned COMPLETE only closes this event.
        """
        entry = self.read()['events'][key]
        if entry['receipt']:
            checked(entry['receipt'])
            return {'action': 'ALREADY_CONSUMED', 'receipt': entry['receipt']}
        if receipt_path is not None and Path(receipt_path).exists():
            try:
                raw = Path(receipt_path).read_bytes()
                receipt = json.loads(raw)
            except (ValueError, UnicodeError):
                return {'action': 'RECONCILE', 'reason': 'PARTIAL_RECEIPT_NO_RETRY'}
            if not isinstance(receipt, dict):
                raise RecoveryError('INVALID_RECEIPT_OBJECT')
            if receipt.get('event_key') != key or receipt.get('request_sha256') != sha(entry['request']):
                raise RecoveryError('RECEIPT_IDENTITY_MISMATCH')
            if type(receipt.get('exit_code')) is not int:
                raise RecoveryError('INVALID_RECEIPT_EXIT_CODE')
            if entry['process'] is not None and receipt.get('process') != entry['process']:
                raise RecoveryError('RECEIPT_PROCESS_MISMATCH')
            if owns(entry['process']) or owns(receipt.get('process')):
                return {'action': 'WAIT_OWNED_EXIT'}
            return {'action': 'ACCEPT_RECEIPT', 'receipt': {
                'path': str(Path(receipt_path).resolve()),
                'sha256': hashlib.sha256(raw).hexdigest()}}
        if exact_job is not None:
            expected = entry['identity']
            if exact_job.get('job_id') != expected['job_id'] or exact_job.get('input_sha256') != expected['input_sha256']:
                raise RecoveryError('EXACT_JOB_IDENTITY_MISMATCH')
            if type(exact_job.get('terminal')) is not bool:
                raise RecoveryError('INVALID_JOB_TERMINAL_FLAG')
            if exact_job['terminal']:
                return {'action': 'CLOSE_AND_SETTLE', 'job_id': expected['job_id']}
            if owns(exact_job.get('process')):
                return {'action': 'CANCEL_OWNED' if self.stopped() else 'WAIT_EXACT_JOB',
                        'job_id': expected['job_id']}
            return {'action': 'RECONCILE', 'reason': 'JOB_HANDLE_MISSING_NO_RETRY'}
        if owns(entry['process']):
            return {'action': 'CANCEL_OWNED' if self.stopped() else 'WAIT_OWNED_WORKER'}
        return {'action': 'RECONCILE', 'reason': 'INTENT_WITHOUT_LIVE_HANDLE_OR_RECEIPT'}

    def consume(self, key, receipt_path):
        self.require_writer()
        observed = self.observe(key, receipt_path=receipt_path)
        if observed['action'] == 'ALREADY_CONSUMED':
            return False
        if observed['action'] != 'ACCEPT_RECEIPT':
            raise RecoveryError('RECEIPT_NOT_READY: ' + observed['action'])
        checked(observed['receipt'])
        state = self.read()
        entry = state['events'][key]
        entry.update(receipt=observed['receipt'], status='RECEIPT_RECORDED')
        # Even nonzero exits retain the full reservation. Decision/schema and
        # evidence acceptance are separate gates in the eventual controller.
        self.save(state)
        return True
"""One durable R6 noninteractive model event; derived from r5_w_batch worker.

The controller reserves the session and commits its exact request first. This
process never submits a job, changes a plan, retries an event or refunds a budget.
"""
from pathlib import Path
import argparse
import json
import os
import signal
import selectors
import subprocess
import time
import jsonschema
from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from rlflow import policy
from tools.r6_recovery import checked, file_pin, Journal

ROOT=Path(__file__).resolve().parents[1]


def write(path,value):atomic(path,canonical(value)+b'\n')


def usage(events):
    """Keep each reported turn; missing provider usage is UNKNOWN, never zero."""
    records=[]; malformed=0
    if events.exists():
        with events.open() as stream:
            for line in stream:
                try: row=json.loads(line)
                except ValueError: malformed+=1;continue
                if row.get('type')=='turn.completed':records.append(row.get('usage','UNKNOWN'))
    return {'reported_turns':records,'malformed_event_lines':malformed,
            'availability':'REPORTED' if records and all(isinstance(r,dict) for r in records) else 'UNKNOWN'}


def validate_request(request):
    required={'prompt','schema','executable','cwd','sandbox','timeout_seconds','output_cap_bytes','stop_paths'}
    if set(request)!=required:raise ValueError('REQUEST_FIELDS')
    prompt=checked(request['prompt']);schema=checked(request['schema']);exe=checked(request['executable'])
    if prompt.stat().st_size>65536:raise ValueError('MODEL_CONTEXT_CAP')
    if request['sandbox'] not in ('read-only','workspace-write','danger-full-access'):raise ValueError('SANDBOX')
    if type(request['timeout_seconds'])not in (int,float) or not 0<request['timeout_seconds']<=3600:raise ValueError('MODEL_TIMEOUT_CAP')
    if type(request['output_cap_bytes'])is not int or not 0<request['output_cap_bytes']<=64*1024**2:raise ValueError('MODEL_OUTPUT_CAP')
    if Path(request['cwd']).resolve()!=ROOT:raise ValueError('WORKSPACE_IDENTITY')
    if not isinstance(request['stop_paths'],list) or not all(isinstance(p,str) and Path(p).is_absolute() for p in request['stop_paths']):raise ValueError('STOP_PATHS')
    value=json.loads(schema.read_text());jsonschema.Draft202012Validator.check_schema(value)
    return prompt,schema,exe,value


def run(directory,key):
    journal=Journal(directory)
    state=journal.read();entry=state['events'][key];request=entry['request']
    if entry['kind']!='model' or entry['resources'].get('automatic_model_sessions')!=1:
        raise ValueError('MODEL_SESSION_NOT_RESERVED')
    if entry['identity']['input_sha256']!=sha(request) or sha(entry['identity'])!=key:raise ValueError('EVENT_IDENTITY')
    if entry['status'] not in ('INTENT','RUNNING') or entry['receipt'] is not None:raise ValueError('EVENT_ALREADY_CONSUMED')
    prompt,schema,executable,schema_value=validate_request(request)
    call=Path(directory)/'calls'/key;call.mkdir(parents=True,exist_ok=True)
    # O_EXCL persists the possible side effect before launching, independent of
    # controller lifetime. A missing receipt does not make this reusable.
    fd=os.open(call/'ONCE',os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    try:os.write(fd,b'one model event\n');os.fsync(fd)
    finally:os.close(fd)
    fd=os.open(call,os.O_DIRECTORY)
    try:os.fsync(fd)
    finally:os.close(fd)
    worker=identity(os.getpid());write(call/'worker.json',{'identity':worker,'event_key':key})
    argv=[str(executable),'-a','never','-s',request['sandbox'],'exec','--json','--color','never',
          '-C',str(ROOT),'--output-schema',str(schema),'--output-last-message',str(call/'last-message.json'),'-']
    write(call/'request.json',{'event_key':key,'request':request,'argv':argv})
    started=time.time();clock=time.monotonic();proc=None;child=None;error=None;code=-1;validated=False
    stops=[Path(p) for p in request['stop_paths']]
    def stopped():return journal.stopped()+policy.stopped(ROOT/'coordination/research')+[str(p) for p in stops if p.exists()]
    interrupted=[]
    def on_signal(signum,frame):interrupted.append(signum)
    previous={s:signal.signal(s,on_signal) for s in (signal.SIGTERM,signal.SIGINT)}
    try:
        if stopped():raise RuntimeError('STOP_BEFORE_MODEL_START')
        env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',GIT_TERMINAL_PROMPT='0')
        with prompt.open('rb') as stdin,(call/'events.jsonl').open('xb') as stdout,(call/'stderr.log').open('xb') as stderr, selectors.DefaultSelector() as selector:
            proc=subprocess.Popen(argv,cwd=ROOT,env=env,stdin=stdin,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
            child=identity(proc.pid)
            if child is None:raise RuntimeError('CHILD_EXIT_BEFORE_IDENTITY')
            write(call/'child.json',{'identity':child,'event_key':key})
            selector.register(proc.stdout,selectors.EVENT_READ,stdout)
            selector.register(proc.stderr,selectors.EVENT_READ,stderr)
            log_bytes=0
            # Leave room for request/identity/receipt and final JSON. Read at
            # most the remaining logging allowance; never first write a huge
            # stdout chunk and discover the cap afterward.
            log_cap=max(0,request['output_cap_bytes']-min(1024**2,request['output_cap_bytes']//4))
            while selector.get_map() or proc.poll() is None:
                if stopped() or interrupted:raise RuntimeError('STOP_DURING_MODEL')
                if time.monotonic()-clock>request['timeout_seconds']:raise RuntimeError('MODEL_TIMEOUT')
                if sum(p.stat().st_size for p in call.iterdir() if p.is_file())>request['output_cap_bytes']:raise RuntimeError('MODEL_OUTPUT_CAP')
                for ready,_ in selector.select(.2):
                    data=os.read(ready.fileobj.fileno(),65536)
                    if not data:
                        selector.unregister(ready.fileobj);ready.fileobj.close();continue
                    if log_bytes+len(data)>log_cap:raise RuntimeError('MODEL_LOG_CAP_BEFORE_WRITE')
                    ready.data.write(data);ready.data.flush();log_bytes+=len(data)
            proc.wait()
        code=proc.returncode
        if code!=0:raise RuntimeError('MODEL_NONZERO_EXIT')
        if sum(p.stat().st_size for p in call.iterdir() if p.is_file())>request['output_cap_bytes']:raise RuntimeError('MODEL_OUTPUT_CAP')
        result=json.loads((call/'last-message.json').read_text())
        jsonschema.validate(result,schema_value)
        validated=True
    except BaseException as exc:error=repr(exc)
    finally:
        if proc is not None:
            if proc.poll() is None:
                if owns(child):os.killpg(child['pgid'],signal.SIGTERM)
                try:proc.wait(timeout=15)
                except subprocess.TimeoutExpired:
                    if owns(child):os.killpg(child['pgid'],signal.SIGKILL)
                    proc.wait(timeout=15)
            code=proc.returncode
        for s,handler in previous.items():signal.signal(s,handler)
    receipt={'event_key':key,'request_sha256':sha(request),'process':worker,'child_identity':child,
             'exit_code':code,'error':error,'started_at':started,'finished_at':time.time(),
             'elapsed_seconds':time.monotonic()-clock,'schema_valid':validated,'usage':usage(call/'events.jsonl'),
             'last_message':file_pin(call/'last-message.json') if (call/'last-message.json').exists() else None,
             'events':file_pin(call/'events.jsonl') if (call/'events.jsonl').exists() else None,
             'stderr':file_pin(call/'stderr.log') if (call/'stderr.log').exists() else None,
             'automatic_retry':False}
    write(call/'receipt.json',receipt)
    return 0 if code==0 and error is None and validated else 1


if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('directory',type=Path);ap.add_argument('event_key')
    a=ap.parse_args();raise SystemExit(run(a.directory.resolve(),a.event_key))

"""CPU motion/geometry scoring for R6's separately registered test schema.

No actor imports, simulator state mutation, or old-suite seed remapping.
Passing motion metrics is necessary but not sufficient: the runner must also
independently validate reset, measurement, force, RNG and artifact provenance.
"""
import math

DIRECTIONS = ((1, 0, 0), (-1, 0, 0), (0, 1, 0), (0, -1, 0),
              (2**-.5, 2**-.5, 0), (-2**-.5, 2**-.5, 0),
              (2**-.5, -2**-.5, 0), (-2**-.5, -2**-.5, 0))
MODES = ('toward', 'away', 'parallel', 'zero')


def norm(v): return math.sqrt(sum(x*x for x in v))
def sub(a, b): return tuple(x-y for x, y in zip(a, b))
def dot(a, b): return sum(x*y for x, y in zip(a, b))
def rms(v): return math.sqrt(sum(x*x for x in v)/len(v))


def vector(v):
    if not isinstance(v, (list, tuple)) or len(v) != 3:
        raise ValueError('VECTOR_SHAPE')
    if any(type(x) not in (int, float) or not math.isfinite(x) for x in v):
        raise ValueError('NONFINITE_VECTOR')
    return tuple(v)


def surface_distance(position, origin):
    x, y, z = sub(vector(position), vector(origin))
    outside = lambda value, lo, hi: max(lo-value, value-hi, 0)
    return min(norm((z, outside(x, -42, 42), outside(y, -42, 42))),
               norm((x-6, outside(y, -6, 6), outside(z, 0, 12))),
               norm((y-6, outside(x, -6, 6), outside(z, 0, 12))))


def lane_role(block, lane):
    if type(lane) is not int or not 0 <= lane < 32:
        raise ValueError('LANE_ID')
    if block['task'] != 'wall_modes':
        return 'd'+str(lane % 8), DIRECTIONS[lane % 8]
    axis = 0 if lane < 16 else 1
    mode = MODES[(lane % 16)//4]
    direction = [0., 0., 0.]
    if mode in ('toward', 'away'): direction[axis] = 1 if mode == 'toward' else -1
    elif mode == 'parallel': direction[1-axis] = 1 if lane % 2 == 0 else -1
    return ('x_wall' if axis == 0 else 'y_wall')+':'+mode, tuple(direction)


def command(block, lane, step):
    _, direction = lane_role(block, lane)
    task = block['task']
    if task == 'wall_modes':
        mode = MODES[(lane % 16)//4]
        active = mode == 'toward' or (mode in ('away', 'parallel') and step < 100)
        factor = 1 if active else 0
    elif task == 'stop': factor = 1 if step < 100 else 0
    elif task == 'reverse': factor = 0 if step < 50 else (1 if step < 125 else -1)
    elif task == 'pulse_hold': factor = 0
    else: raise ValueError('UNKNOWN_TASK')
    return tuple(factor*block['speed_m_s']*x for x in direction)


def consecutive(values, predicate, start=0, end=None, count=11):
    run = 0
    for i in range(start, len(values) if end is None else end):
        run = run+1 if predicate(values[i]) else 0
        if run >= count: return i
    return None


def confirmation(speeds, start, *, boundary='PRE_STEP', limit=3.):
    i = consecutive(speeds, lambda v: v <= .08, start)
    if i is None: return None
    elapsed = (i+1-start if boundary == 'PRE_STEP' else i-start)*.1
    return i if elapsed <= limit+1e-12 else None


def hold(positions, velocities, index, count=201):
    if index is None or len(positions) < index+count: return False
    p = positions[index:index+count]; v = velocities[index:index+count]
    return rms([norm(x) for x in v]) <= .08 and max(norm(sub(x, p[0])[:2]) for x in p) <= .30


def z_gate(positions, velocities, initial):
    return rms([norm(v) for v in velocities]) <= .08 and max(
        norm(sub(p, initial)[:2]) for p in positions) <= .30


def _validate(block, lane, trace, run_id):
    if trace['schema_version'] != 'r6-motion-trace/1' or trace['run_id'] != run_id:
        raise ValueError('TRACE_RUN_IDENTITY')
    if trace['block_id'] != block['id'] or type(trace['lane']) is not int or trace['lane'] != lane:
        raise ValueError('TRACE_LANE_IDENTITY')
    if block['lanes'] != 32 or block['steps'] != (200 if block['task'] == 'reverse' else 330):
        raise ValueError('BLOCK_CONTRACT')
    vector(trace['env_origin_w_m'])
    initial = trace['initial']; rows = trace['rows']
    if not isinstance(rows, list) or len(rows) != block['steps']:
        raise ValueError('MISSING_REQUIRED_SAMPLE')
    episode = initial['episode_id']
    if type(episode) is not int: raise ValueError('EPISODE_ID')
    for i, row in enumerate([initial]+rows):
        vector(row['sensor_position_w_m']); vector(row['velocity_w_m_s'])
        if type(row['episode_id']) is not int or row['episode_id'] != episode:
            raise ValueError('RESET_INTERRUPTED_NO_SPLICE')
        for flag in ('collision', 'height_violation', 'missing'):
            if type(row[flag]) is not bool: raise ValueError('INVALID_FLAG')
            if row[flag]: raise ValueError(flag.upper())
        if type(row['time_s']) not in (int, float) or not math.isfinite(row['time_s']) or abs(row['time_s']-i*.1)>1e-6:
            raise ValueError('OBSERVATION_TIMING')
        if i:
            if type(row['policy_step']) is not int or row['policy_step'] != i-1:
                raise ValueError('POLICY_STEP_SEQUENCE')
            actual = vector(row['command_w_m_s'])
            if norm(sub(actual, command(block, lane, i-1))) > 1e-6:
                raise ValueError('COMMAND_MISMATCH')
    return initial, rows


def score_lane(block, lane, trace, *, run_id):
    """Missing or malformed traces fail in the original registered denominator."""
    group, direction = lane_role(block, lane)
    result = dict(block_id=block['id'], lane=lane, subgroup=group, motion_pass=False,
                  scientific_acceptance='REQUIRES_INDEPENDENT_INPUT_CHAIN_AUDIT', metrics={})
    try:
        initial, rows = _validate(block, lane, trace, run_id)
        positions = [r['sensor_position_w_m'] for r in rows]
        velocities = [r['velocity_w_m_s'] for r in rows]
        speeds = [norm(v) for v in velocities]
        all_positions = [initial['sensor_position_w_m']]+positions
        geometry = [surface_distance(p, trace['env_origin_w_m']) for p in all_positions]
        height = max(abs(p[2]-all_positions[0][2]) for p in all_positions)
        metrics = result['metrics']
        metrics.update(min_distance_m=min(geometry), max_height_deviation_m=height)
        if min(geometry) < .8 or height > .20:
            result['reason'] = 'ALL_TIME_GEOMETRY_OR_HEIGHT'; return result
        task = block['task']
        mode = group.split(':')[-1]
        if task == 'wall_modes' and mode in ('away', 'parallel'): task = 'stop'
        if task == 'stop':
            errors = [norm(sub(velocities[i], command(block, lane, i))) for i in range(100)]
            moving = consecutive(velocities, lambda v: dot(v, direction) >= block['speed_m_s']/2, end=100) is not None
            index = confirmation(speeds, 100)
            metrics.update(incoming_rmse=rms(errors), incoming_stable_rmse=rms(errors[20:]),
                           incoming_vz_rms=rms([v[2] for v in velocities[:100]]),
                           movement_prerequisite=moving, confirmation_index=index)
            passed = moving and metrics['incoming_rmse'] <= .15 and metrics['incoming_stable_rmse'] <= .10 and metrics['incoming_vz_rms'] <= .08 and hold(positions, velocities, index)
        elif task == 'reverse':
            errors = [norm(sub(v, command(block, lane, i))) for i, v in enumerate(velocities)]
            confirmations = [consecutive(errors, lambda e: e <= .10, start, start+30) for start in (50,125)]
            movement = [consecutive(velocities, lambda v, sign=sign: sign*dot(v, direction) >= block['speed_m_s']/2, start, end) is not None for start,end,sign in ((50,125,1),(125,200,-1))]
            projections = [dot(velocities[i], command(block, lane, i))/block['speed_m_s'] for i in range(50,200)]
            metrics.update(nonzero_rmse=rms(errors[50:]), stable_rmse=rms(errors[69:125]+errors[144:]),
                           confirmation_indices=confirmations, movement_prerequisites=movement,
                           peak_projection=max(projections))
            passed = all(i is not None for i in confirmations) and all(movement) and metrics['nonzero_rmse']<=.15 and metrics['stable_rmse']<=.10 and max(projections)<=1.5*block['speed_m_s'] and z_gate(positions[:50], velocities[:50], all_positions[0])
        elif task == 'pulse_hold':
            index = confirmation(speeds, 52)
            metrics['confirmation_index'] = index
            passed = z_gate(positions[:50], velocities[:50], all_positions[0]) and hold(positions, velocities, index)
        elif task == 'wall_modes' and mode == 'zero':
            passed = z_gate(positions, velocities, all_positions[0])
        elif task == 'wall_modes' and mode == 'toward':
            first = next((i for i, d in enumerate(geometry[1:]) if d<=1.1), None)
            index = confirmation(speeds, first if first is not None else 0,
                                 boundary='OBSERVATION' if first is not None else 'PRE_STEP',
                                 limit=3 if first is not None else 20)
            moving = index is not None and consecutive(
                velocities, lambda v: dot(v, direction)>=block['speed_m_s']/2,
                end=max(0, index-10)) is not None
            enough_hold = index is not None and len(rows)-index >= 101
            passed = moving and enough_hold and rms(speeds[index:])<=.08
            metrics.update(trigger_index=first, confirmation_index=index, movement_prerequisite=moving)
        else: raise ValueError('UNKNOWN_TASK')
        result.update(motion_pass=bool(passed), reason='PASS' if passed else 'MOTION_GATE_FAILED')
    except (KeyError, TypeError, ValueError, IndexError, ZeroDivisionError) as exc:
        result.update(reason='INVALID_EVIDENCE', detail=str(exc))
    return result


def wilson(successes, total):
    if total <= 0 or not 0 <= successes <= total: raise ValueError('DENOMINATOR')
    z = 1.959963984540054; p = successes/total; d = 1+z*z/total
    center = (p+z*z/(2*total))/d
    delta = z*math.sqrt(p*(1-p)/total+z*z/(4*total*total))/d
    return [max(0., center-delta), min(1., center+delta)]


def score_block(block, traces, *, run_id):
    """Reject duplicates, preserve missing lanes, never shrink denominators."""
    indexed = {}
    for trace in traces:
        lane = trace.get('lane')
        if type(lane) is not int or not 0<=lane<32 or lane in indexed:
            raise ValueError('DUPLICATE_OR_UNKNOWN_LANE')
        indexed[lane] = trace
    rows = [score_lane(block, lane, indexed.get(lane, {}), run_id=run_id) for lane in range(32)]
    successes = sum(r['motion_pass'] for r in rows)
    groups = {}
    for r in rows: groups.setdefault(r['subgroup'], []).append(r)
    return dict(block_id=block['id'], domain=block['domain'], motion_pass=successes==32,
                successes=successes, total=32, wilson_95=wilson(successes,32), lanes=rows,
                subgroups={k: {'successes':sum(r['motion_pass'] for r in v), 'total':len(v),
                                'wilson_95':wilson(sum(r['motion_pass'] for r in v),len(v))}
                           for k,v in groups.items()},
                scientific_acceptance='REQUIRES_INDEPENDENT_INPUT_CHAIN_AUDIT')
"""Pure CPU R6 reset and force specifications. Privileged setup/evaluation only.

No generated position, lane ID, stream seed, force plan or curriculum clock is
an actor input. Runtime must verify actual reset and applied-force observations.
"""
import hashlib
import json
import math
from training_workloads.unified_h1.robustness import lane_role,vector

YAW_DEGREES=(0,-15,15,-30,30)


def uniform_signed(seed,split,block_id,lane,field):
    if type(seed)is not int or not isinstance(split,str) or not split:
        raise ValueError('EXPLICIT_STREAM_REQUIRED')
    raw=json.dumps(['r6-reset-v1',seed,split,block_id,lane,field],separators=(',',':')).encode()
    # Exact53-bit mapping avoids global RNG mutation and iterator-order coupling.
    integer=int.from_bytes(hashlib.sha256(raw).digest()[:8],'big')>>11
    return 2*(integer/2**53)-1


def rotate_yaw(v,yaw):
    x,y,z=vector(v);c=math.cos(yaw);s=math.sin(yaw)
    return (c*x-s*y,s*x+c*y,z)


def reset_spec(block,*,seed,split,lane,mount_position_m):
    group,direction=lane_role(block,lane)
    mount=vector(mount_position_m)
    yaw_degrees=YAW_DEGREES[(lane//8+lane%8)%5]
    yaw=math.radians(yaw_degrees)
    xy=[.2*uniform_signed(seed,split,block['id'],lane,axis) for axis in ('x','y')]
    sensor=[*xy,2.]
    if block['task']=='wall_modes':sensor[0 if lane<16 else 1]=6-block['sensor_to_wall_distance_m']
    offset=rotate_yaw(mount,yaw)
    root=[a-b for a,b in zip(sensor,offset)]
    return dict(schema_version='r6-reset-spec/1',block_id=block['id'],lane=lane,split=split,
                seed=seed,subgroup=group,sensor_position_local_m=sensor,root_position_local_m=root,
                root_quaternion_wxyz=[math.cos(yaw/2),0.,0.,math.sin(yaw/2)],
                root_linear_velocity_w_m_s=[0.,0.,0.],root_angular_velocity_w_rad_s=[0.,0.,0.],
                yaw_degrees=yaw_degrees,direction_world=list(direction),mount_position_m=list(mount))


def verify_reset(spec,actual,*,position_atol=1e-5,quaternion_atol=1e-6,velocity_atol=1e-6):
    for field in ('sensor_position_local_m','root_position_local_m'):
        if max(abs(a-b) for a,b in zip(vector(actual[field]),vector(spec[field])))>position_atol:
            raise ValueError('RESET_POSITION_MISMATCH:'+field)
    q=actual['root_quaternion_wxyz'];expected=spec['root_quaternion_wxyz']
    if len(q)!=4 or any(type(x)not in (int,float) or not math.isfinite(x) for x in q):raise ValueError('RESET_QUATERNION')
    # q and -q describe the same attitude; compare both without normalizing data.
    if min(max(abs(a-b) for a,b in zip(q,expected)),max(abs(a+b) for a,b in zip(q,expected)))>quaternion_atol:
        raise ValueError('RESET_QUATERNION_MISMATCH')
    for field in ('root_linear_velocity_w_m_s','root_angular_velocity_w_rad_s'):
        if max(abs(x) for x in vector(actual[field]))>velocity_atol:raise ValueError('RESET_VELOCITY_MISMATCH')
    return True


def pulse_force(block,*,lane,physics_tick,mass_kg):
    if type(physics_tick)is not int or physics_tick<0:raise ValueError('PHYSICS_TICK')
    if type(mass_kg)not in (int,float) or not math.isfinite(mass_kg) or mass_kg<=0:raise ValueError('MASS')
    _,direction=lane_role(block,lane)
    active=block['task']=='pulse_hold' and 1000<=physics_tick<1040
    acceleration=block.get('pulse_acceleration_m_s2',0.) if active else 0.
    return tuple(mass_kg*acceleration*x for x in direction)
"""Lossless, quota-before-write R6 measurement-frame archive; no pickle.

Each frame is independently compressed, hashed and fsynced. An interrupted tail
is an error and is preserved. Reader requires the externally expected frame count;
an EOF alone never proves a completed evaluation. This does not replace raw motion.
"""
from pathlib import Path
import hashlib
import json
import os
import struct
import zlib
import numpy as np
from training_workloads.scale_003.persistence import reserve_output_bytes

ARRAY_KEYS = ('clean_ranges', 'clean_validity', 'delivered_ranges', 'delivered_validity',
              'acquisition_time', 'delivery_time', 'frame_age', 'drop', 'frame_available')
MAX_FRAME = 64*1024**2
MAX_HEADER = 64*1024


def canonical(x):return json.dumps(x,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
def digest(raw):return hashlib.sha256(raw).hexdigest()


def encode(frame, *, sequence, run_id, block_id):
    if set(frame) != {*ARRAY_KEYS,'noise_rng_identity'}:raise ValueError('FRAME_FIELDS')
    if type(sequence) is not int or sequence<0 or not run_id or not block_id:raise ValueError('FRAME_IDENTITY')
    identities=frame['noise_rng_identity']
    if not isinstance(identities,list) or not all(isinstance(x,str) and len(x)==64 for x in identities):
        raise ValueError('RNG_IDENTITY')
    fields=[]; parts=[]; prior={}; raw_total=0;offset=0; originals={}
    for name in ARRAY_KEYS:
        value=frame[name]
        if hasattr(value,'detach'):value=value.detach().cpu().numpy()
        a=np.asarray(value)
        if a.dtype.str not in ('<f4','<f8','|b1') or a.ndim!=2:raise ValueError('ARRAY_TYPE')
        if a.shape[0]!=len(identities) or a.shape[0]<=0 or a.shape[1]<=0:raise ValueError('ARRAY_SHAPE')
        boolean=name in ('clean_validity','delivered_validity','drop','frame_available')
        if (a.dtype.kind=='b')!=boolean:raise ValueError('FIELD_DTYPE')
        if name not in ARRAY_KEYS[:4] and a.shape[1]!=1:raise ValueError('TIMESTAMP_SHAPE')
        if name in ARRAY_KEYS[1:4] and a.shape!=originals['clean_ranges'].shape:raise ValueError('BEAM_SHAPE')
        if a.dtype.kind=='f' and not np.isfinite(a).all():raise ValueError('NONFINITE_FRAME')
        a=np.ascontiguousarray(a);raw=a.tobytes();raw_total+=len(raw)
        if raw_total>MAX_FRAME:raise ValueError('FRAME_TOO_LARGE')
        key=(a.dtype.str,a.shape,raw)
        item=dict(name=name,dtype=a.dtype.str,shape=list(a.shape),sha256=digest(raw))
        if key in prior:item['reference']=prior[key]
        else:
            # Byte planes make equal exponent/high-mantissa bytes adjacent;
            # inverse transpose restores the original bytes, including -0.
            shuffled=a.view(np.uint8).reshape(-1,a.dtype.itemsize).T.copy().tobytes()
            compressed=zlib.compress(shuffled,level=3)
            base={'delivered_ranges':'clean_ranges','delivered_validity':'clean_validity'}.get(name)
            if base in originals and originals[base].dtype==a.dtype and originals[base].shape==a.shape:
                xor=np.bitwise_xor(a.view(np.uint8),originals[base].view(np.uint8))
                alternative=zlib.compress(xor.reshape(-1,a.dtype.itemsize).T.copy().tobytes(),level=3)
                if len(alternative)<len(compressed):
                    compressed=alternative;item['xor_base']=base
            item.update(offset=offset,length=len(compressed),raw_bytes=len(raw))
            parts.append(compressed);offset+=len(compressed);prior[key]=name
        fields.append(item)
        originals[name]=a
    payload=b''.join(parts)
    header=canonical(dict(schema_version='r6-range-frame/1',sequence=sequence,run_id=run_id,
                          block_id=block_id,noise_rng_identity=identities,fields=fields,
                          payload_bytes=len(payload),payload_sha256=digest(payload)))
    if len(header)>MAX_HEADER:raise ValueError('HEADER_TOO_LARGE')
    return struct.pack('<I',len(header))+header+payload


def decode(header,payload):
    if header['schema_version']!='r6-range-frame/1' or digest(payload)!=header['payload_sha256']:
        raise ValueError('FRAME_INTEGRITY')
    if [f['name'] for f in header['fields']]!=list(ARRAY_KEYS):raise ValueError('FRAME_FIELDS')
    result={};total=0;offset=0
    for item in header['fields']:
        dtype=np.dtype(item['dtype']);shape=item['shape']
        if dtype.str not in ('<f4','<f8','|b1') or len(shape)!=2 or any(type(n)is not int or n<=0 for n in shape):
            raise ValueError('ARRAY_DESCRIPTOR')
        size=shape[0]*shape[1]*dtype.itemsize;total+=size
        if total>MAX_FRAME:raise ValueError('FRAME_TOO_LARGE')
        if 'reference' in item:
            a=result[item['reference']].copy()
            if a.dtype!=dtype or list(a.shape)!=shape:raise ValueError('REFERENCE_TYPE')
        else:
            length=item['length']
            if type(length)is not int or length<0 or item['offset']!=offset or item['raw_bytes']!=size:
                raise ValueError('PAYLOAD_LAYOUT')
            compressor=zlib.decompressobj()
            raw=compressor.decompress(payload[offset:offset+length],size+1)
            if len(raw)!=size or not compressor.eof or compressor.unused_data or compressor.unconsumed_tail:
                raise ValueError('DECOMPRESSION_BOUND')
            restored=np.frombuffer(raw,dtype=np.uint8).reshape(dtype.itemsize,-1).T.copy()
            if 'xor_base' in item:
                base=result[item['xor_base']]
                if base.dtype!=dtype or list(base.shape)!=shape:raise ValueError('XOR_BASE_TYPE')
                restored=np.bitwise_xor(restored,base.view(np.uint8).reshape(-1,dtype.itemsize))
            a=np.frombuffer(restored.tobytes(),dtype=dtype).reshape(shape).copy();offset+=length
        if digest(a.tobytes())!=item['sha256']:raise ValueError('ARRAY_HASH')
        result[item['name']]=a
    if offset!=len(payload):raise ValueError('UNCONSUMED_PAYLOAD')
    result['noise_rng_identity']=header['noise_rng_identity']
    return result


class RangeArchive:
    def __init__(self,path,*,run_id,block_id,maximum_bytes):
        if type(maximum_bytes)is not int or maximum_bytes<=0:raise ValueError('QUOTA')
        self.path=Path(path);self.run_id=run_id;self.block_id=block_id
        self.maximum=maximum_bytes;self.written=0;self.frames=0
        self.stream=self.path.open('xb')
        self.failed=False
        fd=os.open(self.path.parent,os.O_DIRECTORY)
        try:os.fsync(fd)
        finally:os.close(fd)

    def append(self,frame):
        if self.failed:raise ValueError('PREVIOUS_WRITE_FAILED_PRESERVE_PARTIAL_ARCHIVE')
        record=encode(frame,sequence=self.frames,run_id=self.run_id,block_id=self.block_id)
        if self.written+len(record)>self.maximum:raise ValueError('ARCHIVE_QUOTA_BEFORE_WRITE')
        reserve_output_bytes(self.path,len(record))
        try:
            self.stream.write(record);self.stream.flush();os.fsync(self.stream.fileno())
        except BaseException:
            self.failed=True
            raise
        self.written+=len(record);self.frames+=1

    def close(self):self.stream.close()
    def __enter__(self):return self
    def __exit__(self,*exc):self.close()


def read_archive(path,*,run_id,block_id,expected_frames):
    if type(expected_frames)is not int or expected_frames<=0:raise ValueError('EXPECTED_COUNT_REQUIRED')
    with Path(path).open('rb') as stream:
        for sequence in range(expected_frames):
            prefix=stream.read(4)
            if len(prefix)!=4:raise ValueError('MISSING_OR_PARTIAL_FRAME')
            length=struct.unpack('<I',prefix)[0]
            if not 0<length<=MAX_HEADER:raise ValueError('HEADER_BOUND')
            raw=stream.read(length)
            if len(raw)!=length:raise ValueError('PARTIAL_HEADER')
            header=json.loads(raw)
            if header['run_id']!=run_id or header['block_id']!=block_id or header['sequence']!=sequence:
                raise ValueError('FRAME_IDENTITY')
            size=header['payload_bytes']
            if type(size)is not int or not 0<=size<=MAX_FRAME+MAX_HEADER:raise ValueError('PAYLOAD_BOUND')
            payload=stream.read(size)
            if len(payload)!=size:raise ValueError('PARTIAL_PAYLOAD')
            yield decode(header,payload)
        if stream.read(1):raise ValueError('EXTRA_FRAME_OR_TAIL')
"""R6 range-frame impairment before the shared actor/ICS history interface.

Dormant until explicitly constructed by a registered R6 workload. This module
accepts only measured ranges, validity and time. Clean copies are audit output,
never inputs to the actor/control history. It does not alter the actor schema.
"""
import hashlib
import math
import torch


class RangeDelivery:
    def __init__(self, *, lanes, rays, seed, stream_id, sigma_m=0., delay_cycles=0,
                 device='cpu', dtype=torch.float32):
        if type(lanes) is not int or lanes<=0 or type(rays) is not int or rays<=0:
            raise ValueError('positive tensor dimensions required')
        if type(seed) is not int or not isinstance(stream_id,str) or not stream_id:
            raise ValueError('explicit random stream identity required')
        if type(sigma_m) not in (int,float) or not math.isfinite(sigma_m) or not 0<=sigma_m<=.03:
            raise ValueError('unregistered noise range')
        if type(delay_cycles) is not int or delay_cycles not in (0,1):
            raise ValueError('unregistered delay')
        if dtype not in (torch.float32,torch.float64): raise ValueError('floating dtype required')
        self.lanes,self.rays=lanes,rays
        self.sigma,self.delay=float(sigma_m),delay_cycles
        self.device,self.dtype=torch.device(device),dtype
        self.generators=[];self.streams=[]
        for lane in range(lanes):
            payload=f'R6/range-noise/{seed}/{stream_id}/{lane}'.encode()
            digest=hashlib.sha256(payload).hexdigest()
            generator=torch.Generator(device=self.device)
            generator.manual_seed(int(digest[:16],16)%(2**63))
            self.generators.append(generator);self.streams.append(digest)
        self.pending=self._empty();self.last=self._empty()
        self.last_time=torch.full((lanes,1),-1.,device=self.device,dtype=dtype)

    def _empty(self):
        return dict(ranges=torch.full((self.lanes,self.rays),40.,device=self.device,dtype=self.dtype),
                    valid=torch.zeros((self.lanes,self.rays),device=self.device,dtype=torch.bool),
                    time=torch.zeros((self.lanes,1),device=self.device,dtype=self.dtype),
                    available=torch.zeros((self.lanes,1),device=self.device,dtype=torch.bool))

    def reset(self, indices):
        if not isinstance(indices,torch.Tensor) or indices.dtype!=torch.long or indices.ndim!=1 or indices.device!=self.device:
            raise ValueError('reset indices must be device long vector')
        if bool(((indices<0)|(indices>=self.lanes)).any()): raise ValueError('reset index range')
        for frame in (self.pending,self.last):
            frame['ranges'][indices]=40.;frame['valid'][indices]=False
            frame['time'][indices]=0.;frame['available'][indices]=False
        self.last_time[indices]=-1.
        # Noise streams continue across physical resets; reset does not silently
        # replay the same noise. Full RNG states belong in the experiment record.

    def rng_states(self):
        return [g.get_state().clone() for g in self.generators]

    def deliver(self, ranges_m, validity, acquisition_time_s, drop):
        shape=(self.lanes,self.rays)
        for value,expected,dtype in ((ranges_m,shape,self.dtype),(validity,shape,torch.bool),
                                     (acquisition_time_s,(self.lanes,1),self.dtype),
                                     (drop,(self.lanes,1),torch.bool)):
            if not isinstance(value,torch.Tensor) or value.shape!=expected or value.dtype!=dtype or value.device!=self.device:
                raise ValueError('measurement shape/device/dtype mismatch')
        if not bool(torch.isfinite(ranges_m).all()) or not bool(torch.isfinite(acquisition_time_s).all()):
            raise ValueError('nonfinite producer input')
        if bool((acquisition_time_s<0).any()) or bool((acquisition_time_s<=self.last_time).any()):
            raise ValueError('acquisition timestamp must advance; reset lane explicitly')
        if bool(((ranges_m<.1)|(ranges_m>40.)).any()):
            raise ValueError('producer range outside approved bounds')
        if bool(((~validity)&(ranges_m!=40.)).any()):
            raise ValueError('invalid beam must retain exact 40m fill')
        noisy=ranges_m.clone()
        if self.sigma:
            for lane,generator in enumerate(self.generators):
                mask=validity[lane]
                count=int(mask.sum().item())
                if count:
                    noise=torch.randn((count,),device=self.device,dtype=self.dtype,generator=generator)
                    noisy[lane,mask]=(noisy[lane,mask]+noise.clamp(-3.,3.)*self.sigma).clamp(.1,40.)
        acquired=dict(ranges=noisy,valid=validity.clone(),time=acquisition_time_s.clone(),
                      available=torch.ones((self.lanes,1),device=self.device,dtype=torch.bool))
        candidate=acquired if self.delay==0 else self.pending
        delivered={key:torch.where(drop,self.last[key],value).clone() for key,value in candidate.items()}
        self.pending={k:v.clone() for k,v in acquired.items()}
        self.last={k:v.clone() for k,v in delivered.items()}
        self.last_time.copy_(acquisition_time_s)
        return dict(clean_ranges=ranges_m.clone(),clean_validity=validity.clone(),
                    delivered_ranges=delivered['ranges'],delivered_validity=delivered['valid'],
                    acquisition_time=delivered['time'],delivery_time=acquisition_time_s.clone(),
                    frame_age=acquisition_time_s-delivered['time'],drop=drop.clone(),
                    frame_available=delivered['available'],noise_rng_identity=list(self.streams))

